package com.acaivis.service;
import com.acaivis.model.Order; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service public class EmailService { private final JavaMailSender sender; private final String from; private final String trackingBaseUrl; public EmailService(JavaMailSender sender,@Value("${mail.from:}") String from,@Value("${tracking.base-url:http://localhost:5173/rastrear-pedido}") String trackingBaseUrl){this.sender=sender;this.from=from;this.trackingBaseUrl=trackingBaseUrl;} public boolean sendOrderConfirmation(Order o){if(o.getCustomerEmail()==null||o.getCustomerEmail().isBlank()||from.isBlank()) return false; SimpleMailMessage m=new SimpleMailMessage(); m.setFrom(from); m.setTo(o.getCustomerEmail()); m.setSubject("Açaívis — Pedido "+o.getTrackingCode()+" confirmado"); StringBuilder b=new StringBuilder(); b.append("Olá, ").append(o.getCustomerName()).append("!\n\nRecebemos seu pedido e o pagamento foi confirmado.\n\nSeu pedido: ").append(o.getTrackingCode()).append("\n\nItens:\n"); o.getItems().forEach(i->b.append("- ").append(i.getQuantity()).append("x ").append(i.getProductName()).append(" ").append(i.getSize()).append(" — R$ ").append(i.getSubtotal()).append("\n")); b.append("\nTotal: R$ ").append(o.getTotal()).append("\n\nEntrega: ").append(o.getStreet()).append(", ").append(o.getNumber()).append(" - ").append(o.getNeighborhood()).append(" / ").append(o.getCity()).append("- ").append(o.getState()).append("\n\nAcompanhe seu pedido: ").append(trackingBaseUrl).append("?codigo=").append(o.getTrackingCode()).append("\n\nVocê pode usar o código ").append(o.getTrackingCode()).append(" para acompanhar o status do pedido."); m.setText(b.toString()); sender.send(m); return true; }}
